Here's a toy house that assembles itself brick by brick. You can drag it to orbit, switch to step-by-step instructions, and see the parts list.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "toy_house",
      "catalogId": "https://a2uicatalog.ai/catalog/blocks-b4.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "toy_house",
      "components": [
        {
          "id": "root",
          "component": "brick_build_3d",
          "shape": "house",
          "mode": "animate",
          "orbit": true,
          "height": 440,
          "scrubber": true,
          "checks": true,
          "parts": true,
          "look": "studio",
          "accessibility": {
            "label": "Toy brick house",
            "description": "A 3D toy house that assembles itself from bricks"
          }
        }
      ]
    }
  }
]
</a2ui-json>
